import express from "express";
import Thread from "../models/Thread.js";
import getOpenAIAPIResponse from "../utils/openai.js";
import requireAuth from "../middleware/requireAuth.js";
import { chatLimiter } from "../middleware/rateLimit.js";

const router = express.Router();

//every route below is private: the JWT is read from the HTTP-only cookie
router.use(requireAuth);

//…and budgeted per account, so one user cannot drain the API quota
router.use(chatLimiter);

//thread ids are always UUIDs generated by the frontend; anything else is
//rejected before it can reach a database query
const UUID_PATTERN =
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const MAX_MESSAGE_LENGTH = 8000;

//how many recent messages are sent to the model. Bounded on purpose: long
//threads stay cheap and the model is not buried under stale context. The
//full history is still saved in MongoDB.
const MAX_CONTEXT_MESSAGES = 12;

router.get("/hello", (req, res) => {
    res.send("Chat router is working!");
});

router.get("/test", async (req, res) => {
    try {
        const thread = new Thread({
            threadId:"qwe",
            userId: req.user.id,
            title: "Testing new Thread"
        });

        const response = await thread.save();

        res.send(response);
    } catch (err) {
        console.log(err);
        res.status(500).json({
            error: "Failed to save in DB"
        });
    }
});

router.post("/test", async (req, res) => {
    try {
        const thread = new Thread({
            threadId:"123",
            userId: req.user.id,
            title: "Testing new Thread"
        });

        const response = await thread.save();

        res.send(response);
    } catch (err) {
        console.log(err);
        res.status(500).json({
            error: "Failed to save in DB"
        });
    }
});

router.get("/thread", async(req , res) => {
    try{
        const threads = await Thread.find({ userId: req.user.id }).sort({updatedAt:-1});
        //descending order of updateAt...most recent data on top
        res.json(threads);
    } catch(err) {
        console.log(err);
        res.status(500).json({error:"Failed to fetch threads"});
    }
});


router.get("/thread/:threadId", async(req , res) =>{
    const{threadId} =req.params;

    if(!UUID_PATTERN.test(threadId)){
        return res.status(400).json({error:"Invalid thread id."});
    }

    try{
        //ownership is part of the query: someone else's thread simply is not found
        let thread = await Thread.findOne({threadId, userId: req.user.id});

        if(!thread){
            return res.status(404).json({error:"Thread not found"});
        }
        return res.json(thread.messages);
    } catch(err){
        console.log(err);
        res.status(500).json({error:"Failed to fetch data"});
    }
});

router.delete("/thread/:threadId", async (req,res) => {
      const {threadId} = req.params;

    if(!UUID_PATTERN.test(threadId)){
        return res.status(400).json({error:"Invalid thread id."});
    }

    try{
        const deletedThread = await Thread.findOneAndDelete({threadId, userId: req.user.id});

        if(! deletedThread) {
            return res.status(404).json({error:"Thread not Found"});
        }

        return res.status(200).json({success :"Thread deleted successfully"});

    } catch(err) {
        console.log(err);
         res.status(500).json({error:"Failed to delete thread"});
    }
});

router.post("/chat", async(req, res) =>{
    const {threadId ,message, regenerate} = req.body;

    if(
        typeof threadId !== "string" ||
        typeof message !== "string" ||
        !threadId.trim() ||
        !message.trim()
    ){
        return res.status(400).json({error: "missing required fields "});
    }

    if(!UUID_PATTERN.test(threadId)){
        return res.status(400).json({error: "Invalid thread id."});
    }

    if(message.length > MAX_MESSAGE_LENGTH){
        return res.status(413).json({
            error: `Message must be ${MAX_MESSAGE_LENGTH} characters or fewer.`
        });
    }

    try{
        //never look a thread up by id alone
        const thread = await Thread.findOne({threadId, userId: req.user.id});

        let target;
        if(regenerate === true){
            //regenerating never creates a thread: there must be an existing
            //conversation whose last exchange can be re-answered
            if(!thread || thread.messages.length === 0){
                return res.status(404).json({
                    error: "Nothing to regenerate. Send a message first."
                });
            }
            //drop the assistant reply being replaced. The trailing user
            //message stays and is answered again.
            const lastMessage = thread.messages[thread.messages.length - 1];
            if(lastMessage.role === "assistant"){
                thread.messages.pop();
            }
            target = thread;
        } else if(!thread){
            //owner always comes from the verified token
            target = new Thread({
                threadId,
                userId: req.user.id,
                title:message,
                messages:[{role:"user",content:message}]
            });
        }  else{
            thread.messages.push({role:"user",content:message});
            target = thread;
        }

    //bounded context: the most recent messages of this conversation
    //(always ends with the message to answer)
    const recentMessages = target.messages
        .slice(-MAX_CONTEXT_MESSAGES)
        .map((m) => ({ role: m.role, content: m.content }));

    const assistantReply = await getOpenAIAPIResponse(recentMessages);

    target.messages.push({role:"assistant",content:assistantReply});
    target.updatedAt = new Date();

    await target.save();

    res.json({reply:assistantReply});
    } catch(err){
        if(err.code === 11000){
            return res.status(409).json({
                error: "This conversation ID is already in use. Start a new chat."
            });
        }
        console.log(err);
        //the AI provider is down or out of quota — say so, without the
        //internal error details
        if(err.upstream){
            return res.status(502).json({
                error: "The AI service is currently unavailable. Please try again in a moment."
            });
        }
        //never echo the internal error back to the client
        res.status(500).json({error: "Something went wrong. Please try again."});
    }
});


export default router;
